    persons=[dict(name=p['name'], row=p['rows'][0] + 1, col=p['c0'], up=p.get('up'), down=p.get('down')) for p in persons],
    parent_of={str(k): v for k, v in parent_of.items()},
), open('/app/tree_parsed.json', 'w'), ensure_ascii=False)

