import csv
import re
import sys
from collections import defaultdict

# ---------- load ----------
lines = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
W = max(len(l) for l in lines)
grid = [l.replace('│', '|').ljust(W) for l in lines]
H = len(grid)

people = {}
firsts, lasts = set(), set()
with open('/app/dataset/people_accounts.csv', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        full = f"{row['first_name']} {row['last_name']}"
        if full in people:
            print(f"DUP CSV NAME: {full}", people[full], row['account_balance'])
        people[full] = int(row['account_balance'])
        firsts.add(row['first_name'])
        lasts.add(row['last_name'])

# ---------- tokens ----------
tok_pat = re.compile(r'[A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]+(?: [A-ZĄĆĘŁŃÓŚŹŻ][a-ząćęłńóśźż]+)*')
tokens = []  # (row, start, end, text)
for r, line in enumerate(grid):
    for m in tok_pat.finditer(line):
        if m.group() in ('FAMILY', 'TREE', 'GENERATOR', 'Family'):
            continue
        tokens.append([r, m.start(), m.end(), m.group()])

# ---------- assemble persons ----------
def split_full(text):
    words = text.split(' ')
    for k in range(len(words) - 1, 0, -1):
        first = ' '.join(words[:k]); last = words[k]
        rest = words[k+1:]
        if not rest and first in firsts and last in lasts and f"{first} {last}" in people:
            return first, last
    return None

used = [False] * len(tokens)
persons = []  # dict: name, rows(list), c0, c1
# index tokens by row
by_row = defaultdict(list)
for i, t in enumerate(tokens):
    by_row[t[0]].append(i)

for i, t in enumerate(tokens):
    if used[i]:
        continue
    r, s, e, txt = t
    # try single-row full name
    sf = split_full(txt)
    # try vertical merge with a token on next row at ~same column
    merged = None
    for j in by_row.get(r + 1, []):
        if used[j]:
            continue
        r2, s2, e2, txt2 = tokens[j]
        if abs(s2 - s) <= 2:
            if txt in firsts and txt2 in lasts and f"{txt} {txt2}" in people:
                merged = j
                break
    if sf and merged is not None:
        print(f"AMBIGUOUS at row {r+1} col {s}: '{txt}' alone valid AND merges with '{tokens[merged][3]}'")
    if merged is not None and not sf:
        j = merged
        used[i] = used[j] = True
        persons.append(dict(name=f"{txt} {tokens[j][3]}", rows=[r, r + 1],
                            c0=min(s, tokens[j][1]), c1=max(e, tokens[j][2])))
    elif sf:
        used[i] = True
        persons.append(dict(name=f"{sf[0]} {sf[1]}", rows=[r], c0=s, c1=e))
    # else leave for second pass

# second pass leftovers
for i, t in enumerate(tokens):
    if not used[i]:
        print(f"LEFTOVER token row {t[0]+1} col {t[1]}: '{t[3]}'")

# duplicate person names in tree?
namecount = defaultdict(int)
for p in persons:
    namecount[p['name']] += 1
for n, c in namecount.items():
    if c > 1:
        print(f"DUP TREE NAME: {n} x{c}")

print(f"persons parsed: {len(persons)}")

# ---------- box extents ----------
WIRE = set('|\\/._')
BUSCH = set('-~+')

def find_pipe(row, col, direction):
    # nearest '|' within 4 cols
    for d in range(1, 5):
        c = col + d * direction
        if 0 <= c < W and grid[row][c] == '|':
            return c
    return None

for p in persons:
    Ls, Rs = [], []
    for r in p['rows']:
        lp = find_pipe(r, p['c0'], -1)
        rp = find_pipe(r, p['c1'] - 1, +1)
        if lp is not None: Ls.append(lp)
        if rp is not None: Rs.append(rp)
    p['L'] = min(Ls) if Ls else p['c0'] - 2
    p['R'] = max(Rs) if Rs else p['c1'] + 1
    top, bot = min(p['rows']), max(p['rows'])
    # extend through blank interior rows (pipes at L and R, spaces between)
    def interior(row):
        if row < 0 or row >= H: return False
        seg = grid[row][p['L']:p['R'] + 1]
        inner = seg[1:-1]
        return (seg[0] == '|' or seg[-1] == '|') and inner.strip(' ') == ''
    while interior(top - 1): top -= 1
    while interior(bot + 1): bot += 1
    p['top'] = top; p['bot'] = bot
    p['cx'] = (p['L'] + p['R']) // 2

# ---------- tracing ----------
def cells(r, c, win=2):
    out = []
    for cc in range(max(0, c - win), min(W, c + win + 1)):
        out.append((cc, grid[r][cc]))
    # order by distance from c
    out.sort(key=lambda x: abs(x[0] - c))
    return out

def trace(p, direction):
    """direction=-1 up from top border, +1 down from bottom border.
    Returns (bus_row, col) or ('box', person) or None."""
    # skip border row: one row beyond box interior
    r = (p['top'] - 1 if direction < 0 else p['bot'] + 1)
    # border row may contain -~+ ; skip it if it looks like a border (chars within box span)
    seg = grid[r][p['L']:p['R'] + 1] if 0 <= r < H else ''
    if seg and set(seg) <= (BUSCH | set(' |')) and any(ch in BUSCH for ch in seg):
        # is it border or bus? border stays within box span (allow 1 overhang)
        left_ext = grid[r][max(0, p['L'] - 6):p['L'] - 1]
        right_ext = grid[r][p['R'] + 2:p['R'] + 8]
        if any(ch in BUSCH for ch in left_ext) or any(ch in BUSCH for ch in right_ext):
            # extends beyond box: it's a bus adjacent to box
            return (r, p['cx'])
        r += direction
    c = p['cx']
    blanks = 0
    for _ in range(25):
        if r < 0 or r >= H:
            return None
        cs = cells(r, c)
        wire = next(((cc, ch) for cc, ch in cs if ch in WIRE), None)
        plus = next(((cc, ch) for cc, ch in cs if ch == '+'), None)
        dash = next(((cc, ch) for cc, ch in cs if ch in '-~'), None)
        letter = next(((cc, ch) for cc, ch in cs if ch.isalpha()), None)
        if wire:
            c = wire[0]; r += direction; blanks = 0
        elif plus:
            return (r, plus[0])
        elif dash:
            return (r, dash[0])
        elif letter:
            print(f"TRACE hit letter: {p['name']} dir={direction} at row {r+1} col {letter[0]}")
            return None
        else:
            blanks += 1
            if blanks > 2:
                return None
            r += direction
    return None

for p in persons:
    p['up'] = trace(p, -1)
    p['down'] = trace(p, +1)

# ---------- bus matching ----------
def segments(row, gap):
    segs = []
    start = None; last = None
    for c in range(W):
        if grid[row][c] in BUSCH:
            if start is None:
                start = c
            elif c - last > gap:
                segs.append((start, last)); start = c
            last = c
    if start is not None:
        segs.append((start, last))
    return segs

GAP = 12
bus_rows = defaultdict(lambda: {'parents': [], 'children': []})
for idx, p in enumerate(persons):
    if p['down']:
        bus_rows[p['down'][0]]['parents'].append((p['down'][1], idx))
    if p['up']:
        bus_rows[p['up'][0]]['children'].append((p['up'][1], idx))

parent_of = {}
for row, d in sorted(bus_rows.items()):
    segs = segments(row, GAP)
    def seg_of(col):
        for k, (a, b) in enumerate(segs):
            if a - 2 <= col <= b + 2:
                return k
        return None
    par_by_seg = defaultdict(list)
    for col, idx in d['parents']:
        par_by_seg[seg_of(col)].append(idx)
    for col, idx in d['children']:
        s = seg_of(col)
        ps = par_by_seg.get(s, [])
        if len(ps) == 1:
            parent_of[idx] = ps[0]
        else:
            print(f"MATCH FAIL row {row+1}: child {persons[idx]['name']} col {col} seg {s} parents={[persons[q]['name'] for q in ps]}")

print(f"edges: {len(parent_of)}")
roots = [i for i in range(len(persons)) if i not in parent_of]
print("roots:", [(persons[i]['name'], persons[i]['rows'][0] + 1) for i in roots])

children_of = defaultdict(list)
for c, par in parent_of.items():
    children_of[par].append(c)

# parents with down-junction but no children matched?
for idx, p in enumerate(persons):
    if p['down'] and not children_of.get(idx):
        print(f"PARENT NO KIDS: {p['name']} down={p['down']}")

import json
out = {
    'persons': [dict(name=p['name'], row=p['rows'][0] + 1, col=p['c0']) for p in persons],
    'parent_of': {str(k): v for k, v in parent_of.items()},
}
json.dump(out, open('/app/tree_parsed.json', 'w'), ensure_ascii=False)

