        for c in range(p['L'] - 1, p['R'] + 2):
            box_at[(r, c)] = idx

def bus_density(r, c, win=20):
    if r < 0 or r >= H: return 0
    n = 0
    for cc in range(max(0, c - win), min(W, c + win + 1)):
        if grid[r][cc] in BUSCH and (r, cc) not in box_at:
            n += 1
    return n

# ---------- tracing ----------
def trace(p, direction, debug=False):
    r = (p['top'] - 1 if direction < 0 else p['bot'] + 1)
    # skip the border row of own box
    seg = grid[r][p['L']:p['R'] + 1] if 0 <= r < H else ''
    if seg and set(seg) <= (BUSCH | set(' |')) and any(ch in BUSCH for ch in seg):
        left_ext = grid[r][max(0, p['L'] - 7):p['L'] - 1]
        right_ext = grid[r][p['R'] + 2:p['R'] + 9]
        if any(ch in BUSCH for ch in left_ext) or any(ch in BUSCH for ch in right_ext):
            return ('bus', r, p['cx'])
        r += direction
    c = p['cx']
    blanks = 0
    for _ in range(30):
        if r < 0 or r >= H:
            return None
        # candidate cells ordered by distance from current column
        cand = []
        for cc in range(max(0, c - 2), min(W, c + 3)):
            ch = grid[r][cc]
            if ch != ' ':
                cand.append((abs(cc - c), cc, ch))
        cand.sort()
        moved = False
        for dist, cc, ch in cand:
            if (r, cc) in box_at and box_at[(r, cc)] != None:
                bidx = box_at[(r, cc)]
                if persons[bidx] is not p:
                    return ('box', r, cc, bidx)
            if ch in WIRE:
                c = cc; r += direction; blanks = 0; moved = True
                break
            if ch in BUSCH:
                d0 = bus_density(r, cc)
                if d0 >= 6:
                    # refine: maybe the denser true bus is 1-2 rows further
                    best_r, best_d = r, d0
                    for k in (1, 2):
                        rr = r + k * direction
                        dd = bus_density(rr, cc)
                        if dd > best_d * 1.5 and dd >= 10:
                            best_r, best_d = rr, dd
                    return ('bus', best_r, cc)
                else:
                    # lone noise: step through it
                    c = cc; r += direction; blanks = 0; moved = True
                    break
            if ch.isalpha():
                if debug: print(f"  letter at {r+1},{cc}")
                return None
        if not moved:
            blanks += 1
            if blanks > 2:
                return None
            r += direction
    return None

for idx, p in enumerate(persons):
    p['up'] = trace(p, -1)
    p['down'] = trace(p, +1)

# ---------- matching ----------
def passable(r, c):
    # a column is passable on bus row r if r-1..r+1 has a bus char not inside a box
    for rr in (r, r - 1, r + 1):
        if 0 <= rr < H and grid[rr][c] in BUSCH and (rr, c) not in box_at:
            return True
    return False

def blocked(r, c):
    return (r, c) in box_at

GAP = 6

bus_parents = defaultdict(list)  # row -> [(col, idx)]
for idx, p in enumerate(persons):
    if p['down'] and p['down'][0] == 'bus':
        bus_parents[p['down'][1]].append((p['down'][2], idx))

def walk_find_parents(row, col):
    found = []
    for step in (-1, 1):
        gap = 0
        c = col
        while 0 <= c < W and gap <= GAP:
            c += step
            if c < 0 or c >= W: break
            if blocked(row, c):
                break
            if passable(row, c):
                gap = 0
            else:
                gap += 1
            for pc, pidx in bus_parents.get(row, []):
                if pc == c:
                    found.append((abs(c - col), pidx))
    return found

parent_of = {}
issues = []
for idx, p in enumerate(persons):
    if not p['up']:
        continue
    if p['up'][0] == 'box':
        parent_of[idx] = p['up'][3]
        continue
    row, col = p['up'][1], p['up'][2]
    # direct hit: parent junction at same col
    cands = walk_find_parents(row, col)
    exact = [pi for pc, pi in bus_parents.get(row, []) if abs(pc - col) <= 2]
    if len(set(pi for _, pi in cands)) == 1:
        parent_of[idx] = cands[0][1]
    elif len(cands) == 0:
        issues.append((idx, 'no-parent', row, col))
    else:
        # ambiguous: nearest
        cands.sort()
        parent_of[idx] = cands[0][1]
        issues.append((idx, 'ambig', row, col, [(d, persons[pi]['name']) for d, pi in sorted(cands)]))

for it in issues:
    idx = it[0]
    print("ISSUE", persons[idx]['name'], f"(r{persons[idx]['rows'][0]+1},c{persons[idx]['c0']})", it[1:])

children_of = defaultdict(list)
for c, par in parent_of.items():
    children_of[par].append(c)

roots = [i for i in range(len(persons)) if i not in parent_of]
print(f"edges: {len(parent_of)}, roots: {len(roots)}")
for i in roots:
    if persons[i]['name'] != 'Ewelina Rysz':
        print("  extra root:", persons[i]['name'], persons[i]['rows'][0] + 1, persons[i]['c0'])

for idx, p in enumerate(persons):
    if p['down'] and p['down'][0] == 'bus' and not children_of.get(idx):
        print(f"PARENT NO KIDS: {p['name']} down={p['down']}")

json.dump(dict(
    persons=[dict(name=p['name'], row=p['rows'][0] + 1, col=p['c0'], up=p.get('up'), down=p.get('down')) for p in persons],
    parent_of={str(k): v for k, v in parent_of.items()},
), open('/app/tree_parsed.json', 'w'), ensure_ascii=False)
